	personal_info_decrypt(pi.insu_info ->> ''insu_pat_no'') as insu_pat_no,
  -- personal_info_decrypt(opp.insu_pub_no) as insu_pub_no, --公費負担者番号
	personal_info_decrypt(pi.insu_pub_info ->> ''insu_pub_no'') as insu_pub_no,
  -- personal_info_decrypt(opp.insu_pub_pat_no) as insu_pub_pat_no, --公費負担受給者番号
	personal_info_decrypt(pi.insu_pub_info ->> ''insu_pub_pat_no'') as insu_pub_pat_no,
  -- opp.insu_kbn,--扶養区分
	pi.insu_info ->> ''insu_kbn'' as insu_kbn,
  opp.remarks, --備考欄情報
  opp.insu_dr_id, --保険医ID
  personal_info_decrypt(opp.insu_dr_name) as insu_dr_name,--保険医名称
  personal_info_decrypt(opp.insu_dr_sign) as insu_dr_sign,--保険医署名
  personal_info_decrypt(mpu.anesthesiologist_license_no) as anesthesiologist_license_no,--麻薬施用者番号
  pi.insu_name, --保険名称
	opp.ord_prescription_no
FROM
 ord_personal_prescription opp
 LEFT JOIN mst_personal_user mpu ON opp.insu_dr_id = mpu.user_id and mpu.is_del =''0'' and mpu.is_disp =''1''
 LEFT JOIN pat_insurance pi ON opp.insurance_cd = pi.insurance_cd  and pi.is_del =''0'' and pi.is_disp =''1''
WHERE
opp.is_del =''0'' and opp.is_disp =''1''
and opp.ord_prescription_no = @ordPreNo
 ', 3, '[{"preview": "123456789", "can_calc": "0", "data_code": "insu_no", "data_name": "保険者番号", "data_type": "string", "conv_table": [], "data_class": "処方情報", "field_name": "insu_no", "disp_format": "", "data_category": "処方(最新)", "facility_table": "", "facility_filter_type": "0"}, {"preview": "12345678", "can_calc": "0", "data_code": "insu_pat_mark", "data_name": "被保険者証記号", "data_type": "string", "conv_table": [], "data_class": "処方情報", "field_name": "insu_pat_mark", "disp_format": "", "data_category": "処方(最新)", "facility_table": "", "facility_filter_type": "0"}, {"preview": "1234567", "can_calc": "0", "data_code": "insu_pat_no", "data_name": "被保険者証番号", "data_type": "string", "conv_table": [], "data_class": "処方情報", "field_name": "insu_pat_no", "disp_format": "", "data_category": "処方(最新)", "facility_table": "", "facility_filter_type": "0"}, {"preview": "xxxxxxx", "can_calc": "0", "data_code": "insu_pub1_no", "data_name": "公費負担者番号1", "data_type": "string", "conv_table": [], "data_class": "処方情報", "field_name": "insu_pub1_no", "disp_format": "", "data_category": "処方(最新)", "facility_table": "", "facility_filter_type": "0"}, {"preview": "xxxxxxx", "can_calc": "0", "data_code": "insu_pub2_no", "data_name": "公費負担者番号2", "data_type": "string", "conv_table": [], "data_class": "処方情報", "field_name": "insu_pub2_no", "disp_format": "", "data_category": "処方(最新)", "facility_table": "", "facility_filter_type": "0"}, {"preview": "xxxxxxx", "can_calc": "0", "data_code": "insu_pub3_no", "data_name": "公費負担者番号3", "data_type": "string", "conv_table": [], "data_class": "処方情報", "field_name": "insu_pub3_no", "disp_format": "", "data_category": "処方(最新)", "facility_table": "", "facility_filter_type": "0"}, {"preview": "xxxxxxx", "can_calc": "0", "data_code": "insu_pub4_no", "data_name": "公費負担者番号4", "data_type": "string", "conv_table": [], "data_class": "処方情報", "field_name": "insu_pub4_no", "disp_format": "", "data_category": "処方(最新)", "facility_table": "", "facility_filter_type": "0"}, {"previe